run_generated_snippet: doors = revit_ro.get_elements("Doors")
room_counts = {}
door_ids_by_room = {}
for d in doors:
    rel = revit_ro.get_relationship(d["id"], "rooms_bounding_door")
    if rel == None:
        continue
    for key in ("from_room_id", "to_room_id"):
        rid = rel.get(key)
        if rid != None:
            room_counts[rid] = room_counts.get(rid, 0) + 1
            door_ids_by_room.setdefault(rid, []).append(d["id"])
if not room_counts:
    result = []
else:
    max_count = max(room_counts.values())
    best_rooms = [rid for rid, c in room_counts.items() if c == max_count]
    output = []
    for rid in best_rooms:
        name = revit_ro.get_param(rid, "Name")
        number = revit_ro.get_param(rid, "Number")
        output.append({"room_id": rid, "room_name": name, "room_number": number, "door_count": room_counts[rid], "door_ids": door_ids_by_room.get(rid, [])})
    result = output

